function totalBelanja(barang, kodeDiskon) {
  const subtotal = barang.reduce((jumlah, b) => jumlah + b.harga * b.qty, 0);
  const potongan = kodeDiskon === 'HEMAT10' ? Math.floor(subtotal / 10) : 0;
  return subtotal - potongan;
}

