class GalatDI extends Error {}
const nomor = {};
const tunggal = {};
let total = 0;

function rakit(nama, jejak, peminta) {
  const p = provider[nama];
  if (!p) {
    const asal = peminta ? `dibutuhkan ${peminta}` : 'diminta langsung';
    throw new GalatDI(`galat: ${nama} tidak punya provider (${asal})`);
  }
  if (p.singleton && tunggal[nama]) {
    console.log(`  pakai ${tunggal[nama]}`);
    return;
  }
  if (jejak.includes(nama)) {
    const putaran = [...jejak.slice(jejak.indexOf(nama)), nama];
    throw new GalatDI('siklus: ' + putaran.join(' -> '));
  }
  for (const d of p.dep) rakit(d, [...jejak, nama], nama);
  nomor[nama] = (nomor[nama] || 0) + 1;
  total += 1;
  const label = `${nama}#${nomor[nama]}`;
  if (p.singleton) tunggal[nama] = label;
  console.log(`  buat ${label}`);
}

