const PRODUK = { 1: 'Teh botol', 2: 'Roti bakar' };

function server(req) {
  let res;
  const cocok = req.url.match(/^\/produk\/(\d+)$/);
  if (!req.header.Authorization) {
    res = { kode: 401, isi: JSON.stringify({ galat: 'butuh token' }) };
  } else if (req.metode === 'GET' && cocok) {
    const nama = PRODUK[cocok[1]];
    res = nama
      ? { kode: 200, isi: JSON.stringify({ id: Number(cocok[1]), nama }) }
      : { kode: 404, isi: JSON.stringify({ galat: 'produk tidak ada' }) };
  } else if (req.metode === 'POST' && req.url === '/pesanan') {
    res = { kode: 201, isi: JSON.stringify({ status: 'diterima' }) };
  } else {
    res = { kode: 404, isi: JSON.stringify({ galat: 'rute tidak ada' }) };
  }
  console.log(`  [server] ${res.kode} ${res.isi}`);
  return { ...res, sumber: 'server' };
}

const simpanan = new Map();

const logging = (chain) => {
  const req = chain.request;
  console.log(`--> ${req.metode} ${req.url}`);
  const res = chain.proceed(req);
  console.log(`<-- ${res.kode} ${req.url} (dari ${res.sumber})`);
  return res;
};

const cache = (chain) => {
  const req = chain.request;
  if (req.metode !== 'GET') {
    console.log('  [cache] bukan GET, teruskan');
    return chain.proceed(req);
  }
  if (simpanan.has(req.url)) {
    console.log('  [cache] ada, potong rantai');
    return { ...simpanan.get(req.url), sumber: 'cache' };
  }
  console.log('  [cache] tidak ada, teruskan');
  const res = chain.proceed(req);
  if (res.kode === 200) {
    simpanan.set(req.url, res);
    console.log(`  [cache] simpan ${req.url}`);
  }
  return res;
};

const token = (chain) => {
  console.log('  [token] tambah Authorization');
  const header = { ...chain.request.header, Authorization: 'Bearer rahasia123' };
  return chain.proceed({ ...chain.request, header });
};

function rantai(interceptors, akhir) {
  const jalan = (i, req) => (i === interceptors.length
    ? akhir(req)
    : interceptors[i]({ request: req, proceed: (r) => jalan(i + 1, r) }));
  return (req) => jalan(0, req);
}

const kirim = rantai([logging, cache, token], server);
