  if (a && !b) {
    console.log(`hapus ${jalur} ${label(a)}`);
    hitung.hapus++;
    return;
  }
  if (!a && b) {
    console.log(`tambah ${jalur} ${label(b)}`);
    hitung.tambah++;
    return;
