  if (a.tipe !== b.tipe) {
    console.log(`hapus ${jalur} ${label(a)}`);
    console.log(`tambah ${jalur} ${label(b)}`);
    hitung.hapus++;
    hitung.tambah++;
    return;
  }
  if (a.teks !== b.teks) {
    console.log(`ubah teks ${jalur} ${a.tipe} "${a.teks}" -> "${b.teks}"`);
    hitung.ubah++;
  } else {
    console.log(`tetap ${jalur} ${label(a)}`);
    hitung.tetap++;
  }
  const anakA = a.anak || [];
  const anakB = b.anak || [];
  const n = Math.max(anakA.length, anakB.length);
  for (let i = 0; i < n; i++) {
    banding(anakA[i], anakB[i], `${jalur}.${i}`);
  }
}

