const baris = require('fs').readFileSync(0, 'utf8').split('\n')
  .map((b) => b.trim()).filter((b) => b !== '');

function tulis(s) {
  return `{nilai: ${s.nilai}, status: ${s.status}}`;
}

function reducer(state, event) {
  const [nama, arg] = event.split(' ');
  const n = Number(arg);
  if (nama === 'tambah') return { nilai: state.nilai + n, status: 'siap' };
  if (nama === 'kurang') {
    if (state.nilai - n < 0) return { nilai: state.nilai, status: 'ditolak' };
    return { nilai: state.nilai - n, status: 'siap' };
  }
  if (nama === 'reset') return { nilai: 0, status: 'siap' };
  if (nama === 'muat_gagal') return { nilai: state.nilai, status: 'gagal' };
  return null;
}

const awal = Object.freeze({ nilai: 0, status: 'siap' });
let state = awal;
let dipancarkan = 0;
for (const event of baris) {
  const baru = reducer(state, event);
  if (baru === null) {
    console.log(`event tidak dikenal: ${event}`);
  } else if (baru.nilai === state.nilai && baru.status === state.status) {
    console.log(`${tulis(state)} -> ${event} -> sama, tidak dipancarkan`);
  } else {
    console.log(`${tulis(state)} -> ${event} -> ${tulis(baru)}`);
    state = Object.freeze(baru);
    dipancarkan++;
  }
}
console.log(`state dipancarkan: ${dipancarkan}`);
console.log(`state awal tetap: ${tulis(awal)}`);

const aksi = require('fs').readFileSync(0, 'utf8').split('\n')
  .map((b) => b.trim()).filter((b) => b !== '');

function kurangi(stack, perintah) {
  const [nama, layar] = perintah.split(' ');
  if (nama === 'push') return [...stack, layar];
  if (nama === 'navigate') {
    const i = stack.lastIndexOf(layar);
    if (i === -1) return [...stack, layar];
    return stack.slice(0, i + 1);
  }
  if (nama === 'goBack') {
    if (stack.length === 1) return null;
    return stack.slice(0, -1);
  }
  if (nama === 'reset') return [layar];
  throw new Error(`aksi tidak dikenal: ${perintah}`);
}

let stack = ['Beranda'];
console.log(`awal -> [${stack.join(', ')}]`);
for (const perintah of aksi) {
  const baru = kurangi(stack, perintah);
  if (baru === null) {
    console.log(`${perintah} -> diabaikan, sudah di layar pertama`);
    continue;
  }
  stack = baru;
  console.log(`${perintah} -> [${stack.join(', ')}]`);
}
console.log(`layar aktif: ${stack[stack.length - 1]}`);

const baris = require('fs').readFileSync(0, 'utf8').split('\n')
  .map((b) => b.trim()).filter((b) => b !== '');
const berkas = baris[0].split(/\s+/);
const daftarUrl = baris.slice(1);

function keRute(jalur) {
  const ruas = jalur.replace(/^app\//, '').replace(/\.tsx$/, '').split('/');
  if (ruas[ruas.length - 1] === 'index') ruas.pop();
  return ruas.filter((r) => !/^\(.*\)$/.test(r));
}

const rute = [];
let tidakKetemu = null;
for (const jalur of berkas) {
  const nama = jalur.split('/').pop();
  if (nama === '+not-found.tsx') {
    tidakKetemu = jalur;
  } else if (!nama.startsWith('_')) {
    rute.push({ jalur, ruas: keRute(jalur) });
  }
}

function cocok(ruasRute, ruasUrl) {
  const param = [];
  const bobot = [];
  for (let i = 0; i < ruasRute.length; i++) {
    const r = ruasRute[i];
    const sisa = /^\[\.\.\.(\w+)\]$/.exec(r);
    if (sisa) {
      if (i !== ruasRute.length - 1 || i >= ruasUrl.length) return null;
      param.push(`${sisa[1]}=${ruasUrl.slice(i).join('/')}`);
      bobot.push(2);
      return { param, bobot };
    }
    if (i >= ruasUrl.length) return null;
    const dinamis = /^\[(\w+)\]$/.exec(r);
    if (dinamis) {
      param.push(`${dinamis[1]}=${ruasUrl[i]}`);
      bobot.push(1);
    } else if (r === ruasUrl[i]) {
      bobot.push(0);
    } else {
      return null;
    }
  }
  if (ruasRute.length !== ruasUrl.length) return null;
  return { param, bobot };
}

function lebihSpesifik(a, b) {
  const n = Math.min(a.bobot.length, b.bobot.length);
  for (let i = 0; i < n; i++) {
    if (a.bobot[i] !== b.bobot[i]) return a.bobot[i] < b.bobot[i];
  }
  return a.jalur < b.jalur;
}

for (const url of daftarUrl) {
  const ruasUrl = url.split('?')[0].split('/').filter((r) => r !== '');
  let terbaik = null;
  for (const r of rute) {
    const hasil = cocok(r.ruas, ruasUrl);
    if (!hasil) continue;
    const calon = { jalur: r.jalur, ...hasil };
    if (!terbaik || lebihSpesifik(calon, terbaik)) terbaik = calon;
  }
  if (terbaik) {
    const p = terbaik.param.length ? ` (${terbaik.param.join(', ')})` : '';
    console.log(`${url} -> ${terbaik.jalur}${p}`);
  } else if (tidakKetemu) {
    console.log(`${url} -> 404, tampilkan ${tidakKetemu}`);
  } else {
    console.log(`${url} -> 404`);
  }
}

const baris = require('fs').readFileSync(0, 'utf8').split('\n')
  .map((b) => b.trim()).filter((b) => b !== '');

// Sisi native tiruan: plugin dan metodenya.
const simpanan = {};
let nomorFoto = 0;
const plugin = {
  Perangkat: {
    info: () => ({ platform: 'android', model: 'Tiruan' }),
  },
  Kamera: {
    ambilFoto: (arg) => {
      const kualitas = arg.kualitas === undefined ? 90 : arg.kualitas;
      if (kualitas < 1 || kualitas > 100) throw new Error('kualitas harus 1 sampai 100');
      nomorFoto += 1;
      return { jalur: `foto_${nomorFoto}.jpg`, kualitas };
    },
  },
  Simpan: {
    set: (arg) => {
      simpanan[arg.kunci] = arg.nilai;
      return {};
    },
    get: (arg) => ({ nilai: arg.kunci in simpanan ? simpanan[arg.kunci] : null }),
  },
};

const antrean = [];
const menunggu = new Map();

function terimaDiWeb(teks) {
  const balasan = JSON.parse(teks);
  const { selesai, gagal } = menunggu.get(balasan.id);
  menunggu.delete(balasan.id);
  if ('galat' in balasan) gagal(new Error(balasan.galat));
  else selesai(balasan.hasil);
}

function prosesDiNative() {
  while (antrean.length > 0) {
    const pesan = JSON.parse(antrean.shift());
    let balasan;
    const p = plugin[pesan.plugin];
    if (!p) {
      balasan = { id: pesan.id, galat: `plugin ${pesan.plugin} belum terpasang` };
    } else if (!p[pesan.metode]) {
      balasan = { id: pesan.id, galat: `metode ${pesan.metode} tidak ada di ${pesan.plugin}` };
    } else {
      try {
        balasan = { id: pesan.id, hasil: p[pesan.metode](pesan.argumen) };
      } catch (e) {
        balasan = { id: pesan.id, galat: e.message };
      }
    }
    if ('galat' in balasan) console.log(`native #${balasan.id} -> galat: ${balasan.galat}`);
    else console.log(`native #${balasan.id} -> ${JSON.stringify(balasan.hasil)}`);
    terimaDiWeb(JSON.stringify(balasan));
  }
}

// Sisi web: setiap panggilan jadi pesan JSON bernomor dan sebuah Promise.
let nomor = 0;
function panggil(namaPlugin, metode, argumen) {
  nomor += 1;
  const id = nomor;
  const teks = JSON.stringify({ id, plugin: namaPlugin, metode, argumen });
  console.log(`kirim #${id} ${namaPlugin}.${metode} ${JSON.stringify(argumen)}`);
  antrean.push(teks);
  return new Promise((selesai, gagal) => menunggu.set(id, { selesai, gagal }));
}

const janji = baris.map((b) => {
  const spasi = b.indexOf(' ');
  const nama = spasi === -1 ? b : b.slice(0, spasi);
  const argumen = spasi === -1 ? {} : JSON.parse(b.slice(spasi + 1));
  const [namaPlugin, metode] = nama.split('.');
  return { nama, promise: panggil(namaPlugin, metode, argumen) };
});

prosesDiNative();

Promise.allSettled(janji.map((j) => j.promise)).then((hasil) => {
  hasil.forEach((h, i) => {
    const awal = `Promise #${i + 1} ${janji[i].nama}`;
    if (h.status === 'fulfilled') console.log(`${awal} selesai: ${JSON.stringify(h.value)}`);
    else console.log(`${awal} ditolak: ${h.reason.message}`);
  });
});

