const { EventEmitter } = require('events');

// Proses main tiruan. Catatan disimpan di memori, bukan di disk.
const catatan = new Map();
const ipcMain = new EventEmitter();

function handle(kanal, fungsi) {
  ipcMain.on(kanal, (args, balas) => {
    try {
      balas(null, fungsi(...args));
    } catch (e) {
      balas(e.message);
    }
  });
}

function cekJudul(judul) {
  if (!/^[a-z0-9_-]+$/.test(judul || '')) throw new Error('judul tidak sah');
}

handle('simpan_catatan', (judul, ...kata) => {
  cekJudul(judul);
  const isi = kata.join(' ');
  catatan.set(judul, isi);
  return `tersimpan: ${judul} (${isi.length} huruf)`;
});

handle('baca_catatan', (judul) => {
  cekJudul(judul);
  if (!catatan.has(judul)) throw new Error(`catatan ${judul} tidak ada`);
  return catatan.get(judul);
});

handle('daftar_catatan', () => {
  const semua = [...catatan.keys()].sort();
  return semua.length ? semua.join(', ') : '(kosong)';
});

// Handler berbahaya ini ada di main, tapi sengaja tidak dibuka preload.
handle('hapus_semua', () => {
  catatan.clear();
  return 'semua catatan dihapus';
});

// Preload tiruan: cuma kanal di daftar ini yang boleh dipanggil renderer.
const IZIN = ['baca_catatan', 'simpan_catatan', 'daftar_catatan'];

function invoke(kanal, args) {
  if (!IZIN.includes(kanal)) return `ditolak: kanal ${kanal} tidak diizinkan`;
  let hasil = 'galat: tidak ada handler';
  ipcMain.emit(kanal, args, (galat, nilai) => {
    hasil = galat ? `galat: ${galat}` : nilai;
  });
  return `${kanal} -> ${hasil}`;
}

const baris = require('fs').readFileSync(0, 'utf8').split('\n');
for (const b of baris) {
  if (!b.trim()) continue;
  const [kanal, ...args] = b.trim().split(/\s+/);
  console.log(invoke(kanal, args));
}

const LEBAR = 26;
const TINGGI = 3;

let grid = [];
let klik = null;   // {x, y} atau null, berlaku satu frame
let hitung = 0;    // state milik aplikasi, bukan milik tombol

function mulaiFrame(k) {
  grid = Array.from({ length: TINGGI }, () => Array(LEBAR).fill(' '));
  klik = k;
}

function tulis(teks, x, y) {
  for (let i = 0; i < teks.length; i++) grid[y][x + i] = teks[i];
}

function tombol(label, x, y) {
  const kotak = `[${label}]`;
  tulis(kotak, x, y);
  return klik !== null && klik.y === y && klik.x >= x && klik.x < x + kotak.length;
}

function ui() {
  if (tombol('Tambah', 0, 0)) hitung++;
  if (hitung > 0 && tombol('Kurang', 9, 0)) hitung--;
  if (tombol('Reset', 18, 0)) hitung = 0;
  tulis(`Nilai: ${hitung}`, 0, 2);
}

const baris = require('fs').readFileSync(0, 'utf8').split('\n')
  .map((b) => b.trim()).filter((b) => b !== '');

baris.forEach((b, i) => {
  const k = b === '-' ? null : { x: Number(b.split(' ')[0]), y: Number(b.split(' ')[1]) };
  mulaiFrame(k);
  ui();
  console.log(`frame ${i + 1} (klik ${b})`);
  console.log('+' + '-'.repeat(LEBAR) + '+');
  for (const r of grid) console.log('|' + r.join('') + '|');
  console.log('+' + '-'.repeat(LEBAR) + '+');
});

const teks = require('fs').readFileSync(0, 'utf8');
const [bagianAturan, bagianMinta] = teks.split(/^---$/m);

// aturan[koleksi][jenis] = ekspresi
const aturan = {};
for (const b of bagianAturan.split('\n')) {
  const m = b.trim().match(/^aturan (\S+) (baca|tulis): (.+)$/);
  if (!m) continue;
  aturan[m[1]] = aturan[m[1]] || {};
  aturan[m[1]][m[2]] = m[3].trim();
}

function nilai(token, konteks) {
  if (token === 'null') return null;
  if (token === 'true') return true;
  if (token === 'false') return false;
  if (/^'.*'$/.test(token)) return token.slice(1, -1);
  if (token === 'auth') return konteks.auth;
  if (token === 'auth.uid') {
    if (konteks.auth === null) throw new Error('auth null');
    return konteks.auth.uid;
  }
  if (token.startsWith('data.')) {
    const v = konteks.data[token.slice(5)];
    if (v === undefined) throw new Error('medan tidak ada');
    return v;
  }
  throw new Error(`token tidak dikenal: ${token}`);
}

function syarat(teksSyarat, konteks) {
  const t = teksSyarat.trim().split(/\s+/);
  if (t.length === 1) return nilai(t[0], konteks) === true;
  const [kiri, op, kanan] = t;
  const a = nilai(kiri, konteks);
  const b = nilai(kanan, konteks);
  return op === '==' ? a === b : a !== b;
}

// Galat saat evaluasi (misalnya auth.uid padahal belum masuk) = tolak.
function evaluasi(ekspresi, konteks) {
  try {
    return ekspresi.split('&&').every((s) => syarat(s, konteks)) ? 'izin' : 'tolak';
  } catch (e) {
    return `tolak (galat: ${e.message})`;
  }
}

const JENIS = { baca: 'baca', buat: 'tulis', ubah: 'tulis', hapus: 'tulis' };

for (const b of bagianMinta.split('\n')) {
  const kata = b.trim().split(/\s+/);
  if (kata[0] === '') continue;
  const [operasi, jalur, ...pasangan] = kata;
  const [koleksi] = jalur.split('/');
  const konteks = { auth: null, data: {} };
  for (const p of pasangan) {
    const [k, v] = p.split('=');
    if (k === 'auth') konteks.auth = v === 'null' ? null : { uid: v };
    else konteks.data[k] = v;
  }
  const siapa = konteks.auth ? konteks.auth.uid : 'tamu';
  const jenis = JENIS[operasi];
  const ekspresi = aturan[koleksi] && aturan[koleksi][jenis];
  if (ekspresi === undefined) {
    console.log(`${operasi} ${jalur} (${siapa}): tolak [tidak ada aturan]`);
    continue;
  }
  const hasil = evaluasi(ekspresi, konteks);
  console.log(`${operasi} ${jalur} (${siapa}): ${hasil} [${koleksi} ${jenis}: ${ekspresi}]`);
}

const baris = require('fs').readFileSync(0, 'utf8').split('\n')
  .map((b) => b.trim()).filter((b) => b !== '');

const lane = {};
const hasil = {};
let selalu = [];
const antrean = [];

for (const b of baris) {
  let m;
  if ((m = b.match(/^lane (\S+): (.+)$/))) {
    lane[m[1]] = m[2].split(/\s+/);
  } else if ((m = b.match(/^selalu: (.+)$/))) {
    selalu = m[1].split(/\s+/);
  } else if ((m = b.match(/^hasil (\S+): (ok|gagal)\s*(.*)$/))) {
    hasil[m[1]] = { status: m[2], ket: m[3] };
  } else if ((m = b.match(/^jalankan (\S+)$/))) {
    antrean.push(m[1]);
  }
}

function jalankan(nama) {
  const langkah = lane[nama];
  if (!langkah) {
    console.log(`[${nama}] lane tidak ada`);
    return;
  }
  console.log(`[${nama}] mulai (${langkah.length} langkah)`);
  let gagalDi = null;
  langkah.forEach((l, i) => {
    const posisi = `${i + 1}/${langkah.length}`;
    if (gagalDi) {
      console.log(`[${nama}] ${posisi} ${l}: dilewati`);
      return;
    }
    const h = hasil[l] || { status: 'ok', ket: '' };
    const ket = h.ket ? ` (${h.ket})` : '';
    console.log(`[${nama}] ${posisi} ${l}: ${h.status}${ket}`);
    if (h.status === 'gagal') gagalDi = l;
  });
  const ringkas = gagalDi ? `${nama} gagal di ${gagalDi}` : `${nama} berhasil`;
  for (const s of selalu) {
    console.log(`[${nama}] selalu ${s}: "${ringkas}"`);
  }
  console.log(`[${nama}] selesai: ${gagalDi ? 'gagal' : 'berhasil'}`);
}

antrean.forEach(jalankan);

const data = {};
for (const b of require('fs').readFileSync(0, 'utf8').split('\n')) {
  const i = b.indexOf('=');
  if (i > 0) data[b.slice(0, i).trim()] = b.slice(i + 1).trim();
}

const tanggal = data.tanggal;           // YYYY-MM-DD, bisa dibandingkan sebagai teks
const target = Number(data.targetSdk);
const kodeBaru = Number(data.versionCode);
const kodeLama = data.versionCode_lama ? data.versionCode_lama.split(',').map(Number) : [];
const pelanggaran = [];

// 1. Aplikasi baru wajib Android App Bundle (AAB).
if (data.aplikasi === 'baru' && data.format !== 'aab') {
  pelanggaran.push(`format ${data.format}: aplikasi baru wajib AAB`);
}

// 2. Target API: 36 sejak 2026-08-31, perpanjangan sampai 2026-11-01.
const batas = data.perpanjangan === 'ya' ? '2026-11-01' : '2026-08-31';
const wajib = tanggal >= batas ? 36 : 35;
if (target < wajib) {
  pelanggaran.push(`targetSdk ${target} < ${wajib} untuk rilis ${tanggal}` +
    (wajib === 36 ? ` (berlaku sejak ${batas})` : ''));
}

// 3. versionCode harus lebih besar dari semua yang pernah diunggah.
const tertinggi = kodeLama.length ? Math.max(...kodeLama) : 0;
if (kodeBaru <= tertinggi) {
  pelanggaran.push(`versionCode ${kodeBaru} harus lebih besar dari ${tertinggi}`);
}

// 4. Akun pribadi yang dibuat sesudah 2023-11-13: uji tertutup dulu.
const wajibUji = data.jalur === 'produksi' && data.akun === 'pribadi' &&
  data.akun_dibuat > '2023-11-13' && data.sudah_produksi !== 'ya';
if (wajibUji) {
  const penguji = Number(data.penguji || 0);
  const hari = Number(data.hari_uji || 0);
  if (penguji < 12) pelanggaran.push(`uji tertutup baru ${penguji} penguji, butuh minimal 12`);
  if (hari < 14) pelanggaran.push(`uji tertutup baru ${hari} hari berturut-turut, butuh 14`);
}

console.log(`periksa rilis ${data.tanggal} ke jalur ${data.jalur}`);
for (const p of pelanggaran) console.log(`- ${p}`);
console.log(pelanggaran.length ? `hasil: ${pelanggaran.length} pelanggaran` : 'hasil: siap rilis');

const baris = require('fs').readFileSync(0, 'utf8').split('\n')
  .map((b) => b.trim()).filter((b) => b !== '');

const LAIN = 'laptop';           // perangkat lain yang mengubah langsung di server
let klienId = 'hp';
const server = new Map();         // id -> {teks, versi, oleh}
const klien = new Map();          // salinan lokal di perangkat ini
const antrean = [];               // mutasi yang menunggu dikirim
const konflik = [];
let online = true;
let nomorAntre = 0;

function salin(c) {
  return { teks: c.teks, versi: c.versi, oleh: c.oleh };
}

function tarik() {
  for (const [id, c] of server) klien.set(id, salin(c));
}

// Last-writer-wins: versi lebih tinggi menang; kalau seri, id klien yang
// lebih awal menurut abjad menang. Hasilnya teks untuk log.
function kirim(m) {
  const s = server.get(m.id);
  let terima = true;
  let ket = 'diterima';
  if (s && s.versi !== m.dasar) {
    let menang;
    let alasan = 'versi lebih tinggi';
    if (m.versi > s.versi) menang = klienId;
    else if (m.versi < s.versi) menang = s.oleh;
    else {
      menang = klienId < s.oleh ? klienId : s.oleh;
      alasan = 'seri, abjad';
    }
    terima = menang === klienId;
    ket = `konflik dengan ${s.oleh} v${s.versi}, ${terima ? 'diterima' : 'ditolak'}`;
    konflik.push(`${m.id}: ${klienId} v${m.versi} vs ${s.oleh} v${s.versi} -> ` +
      `${menang} menang (${alasan})`);
  }
  if (terima) server.set(m.id, { teks: m.teks, versi: m.versi, oleh: klienId });
  return ket;
}

for (const b of baris) {
  const [perintah, id, ...kata] = b.split(/\s+/);
  const teks = kata.join(' ');
  if (perintah === 'klien') {
    klienId = id;
  } else if (perintah === 'offline') {
    online = false;
    console.log(`${klienId} offline`);
  } else if (perintah === 'online') {
    online = true;
    console.log(`${klienId} online, kirim ${antrean.length} mutasi`);
    for (const m of antrean.splice(0)) {
      console.log(`  #${m.no} ${m.id} v${m.versi}: ${kirim(m)}`);
    }
    tarik();
    console.log(`  tarik ${server.size} catatan dari server`);
  } else if (perintah === 'ubah') {
    const lama = klien.get(id);
    const dasar = lama ? lama.versi : 0;
    const m = { id, teks, versi: dasar + 1, dasar };
    klien.set(id, { teks, versi: m.versi, oleh: klienId });
    if (online) {
      console.log(`${klienId}: ubah ${id} "${teks}" v${m.versi}, ${kirim(m)}`);
      tarik();
    } else {
      m.no = ++nomorAntre;
      antrean.push(m);
      console.log(`${klienId} (offline): ubah ${id} "${teks}" v${m.versi}, antre #${m.no}`);
    }
  } else if (perintah === 'server_ubah') {
    const s = server.get(id);
    const versi = (s ? s.versi : 0) + 1;
    server.set(id, { teks, versi, oleh: LAIN });
    console.log(`${LAIN}: ubah ${id} "${teks}" v${versi} di server` +
      (online ? `, ${klienId} ikut menerima` : ''));
    if (online) tarik();
  }
}

function cetak(judul, peta) {
  console.log(judul);
  for (const id of [...peta.keys()].sort()) {
    const c = peta.get(id);
    console.log(`  ${id} v${c.versi} ${c.oleh}: ${c.teks}`);
  }
}

console.log(konflik.length ? 'konflik:' : 'konflik: tidak ada');
for (const k of konflik) console.log(`  ${k}`);
cetak('isi akhir klien:', klien);
cetak('isi akhir server:', server);
const sama = JSON.stringify([...klien].sort()) === JSON.stringify([...server].sort());
console.log(`sama: ${sama ? 'ya' : 'tidak'}`);
